// Manual control-flow notes. Rendering and source anchors are bookkeeping, not a semantic extractor.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const root = '/Users/carlos/Documents/Drogon-mentu-session';
const area = 'docs/migration/audit-closure/e4-cli';
const contracts = [];
const assertions = [];
const sha = s => crypto.createHash('sha256').update(s).digest('hex');
function evidence(file, first = 1, last) {
  const bytes = fs.readFileSync(path.join(root, file));
  const lines = bytes.toString().trimEnd().split('\n');
  const end = last ?? lines.length;
  if (first < 1 || end > lines.length || end < first) throw Error(`Invalid anchor ${file}:${first}-${end}`);
  return { path: file, line: first, endLine: end, sha256: sha(bytes), rangeSha256: sha(lines.slice(first - 1, end).join('\n')), readScope: first === 1 && end === lines.length ? 'full_file_body_read' : 'explicit_range_body_read' };
}
function add(id, gap, title, files, behavior, remainingTests, sourceOmissions = []) {
  contracts.push({ id, gap, title, sourceEvidence: files.map(f => typeof f === 'string' ? evidence(f) : evidence(...f)), behavior, remainingTests, sourceOmissions, execution: 'not_run' });
}
function assertion(file, covered, limitations, first = 1, last) {
  assertions.push({ ...evidence(file, first, last), covered, limitations, execution: 'not_run', preservation: 'Port assertion bodies without weakening; fixture changes require explicit contract mapping.' });
}

add('S2-schedule', 'E4-S2', 'Cron and RRULE validation and occurrence search', [
  'src/shared/automation-schedule-parsing.ts', 'src/shared/automation-schedule-occurrences.ts', 'src/shared/automation-cron-occurrence.ts',
  'src/shared/clipboard-text.ts', 'src/shared/utf8-byte-limits.ts'
], [
  'Ownership: pure caller-side validation and local Date arithmetic; this is not a remote scheduler execution guarantee. S1 automations create/update validate before destination mutation, but earlier target resolution may already perform RPCs; destination ordering is not a zero-prior-RPC guarantee.',
  'parseSchedule trims and chooses RRULE whenever the string contains =. RRULE splits semicolon entries then =, uppercases keys only, ignores unknown fields and lets the last duplicate key win. FREQ must exactly be HOURLY, DAILY or WEEKLY; BYHOUR defaults 9 and BYMINUTE 0, both Number-coerced then integer/range checked (0..23, 0..59). Weekly BYDAY is a nonempty comma list of exact SU/MO/TU/WE/TH/FR/SA with no token trimming; daily/hourly do not validate or use BYDAY.',
  'Cron rejects expressions over 2048 UTF-8 bytes before tokenization, admits the explicitly enumerated Unicode whitespace classes, and requires five fields. UTF-16 length short-circuits oversize; UTF-8 measurement pairs only in-bounds surrogate pairs, counts lone surrogates as three bytes, and stops strictly above the byte limit.',
  'Each cron field supports comma unions, inclusive ranges and at most one slash with integer step >=1. Empty components, malformed ranges, reversed/out-of-bounds endpoints and invalid names throw. Number coercion admits numeric spellings beyond plain decimal; month and weekday names are case-insensitive. Bounds are minute 0..59/hour 0..23/day 1..31/month 1..12/weekday 0..7, with Sunday 7 normalized to 0. A singleton/step is still a singleton. Restricted day flags derive from expanded set sizes, not the original star spelling.',
  'Month must match; day-of-month/day-of-week use OR when both restricted, otherwise AND. isValid* catches parse errors and rejects cron with no possible matching date over nine leap-year-sized years; date possibility does not independently inspect time fields. RRULE validity only parses. Cron-only validator rejects RRULE.',
  'Preset builders floor/clamp hour, minute and weekday (weekday default Monday); hourly omits BYHOUR, weekdays uses fixed MO,TU,WE,TH,FR order. parseAutomationRrule recognizes that exact ordered weekday list, otherwise weekly must have one day; tryParse returns null on unsupported presets.',
  'Next occurrence is strictly after afterMs and >=dtstart; cron starts at minute floor and scans at most 9*366 days of minutes. Latest is <=now and >=dtstart, returns null when now<dtstart/no candidate. Hourly aligns minute then advances/backtracks one hour. Daily/weekly iterate local calendar candidates with fixed DAY_MS increments and finite 370-day searches. DST, invalid timestamps and scan exhaustion require explicit fixtures; no timezone conversion is supplied here.'
], [
  'Port automation-schedules.test.ts and index-automation-schedule.test.ts; assert accepted/rejected inputs and absence of destination mutation on validation failure while preserving earlier target-resolution RPC ordering.',
  'Add exact 2048/2049-byte ASCII, multibyte and lone-surrogate cases; duplicate RRULE keys, unknown fields, FREQ/BYDAY case and whitespace; each field boundary, numeric exponent/hex, empty union, singleton/step, Sunday ranges, full-set DOM/DOW OR/AND.',
  'Run fixed timezone fixtures around both DST transitions, leap day, dtstart equality/off-minute, after/now boundary, invalid Date and horizon exhaustion; characterize baseline behavior before deciding whether to preserve anomalies.'
]);

add('S2-context', 'E4-S2', 'Task source and workspace run context normalization', [
  'src/shared/task-source-context.ts', 'src/shared/task-provider-identity.ts'
], [
  'Ownership: caller-side payload construction; declared host ownership is data, not permission to read a remote filesystem locally.',
  'normalizeTaskSourceContext requires a trimmed nonempty projectId and exact github/gitlab/linear/jira provider; fixes kind to task-source, defaults missing/invalid hostId to local, and normalizes optional setup/repo/account strings to trimmed string or null. Direct normalization ignores incoming kind. Stored normalization first validates object/provider/project/kind/scalar/identity shape; nonblank malformed host rejects instead of silently defaulting.',
  'Provider identity must be an object with matching provider; mismatch normalizes to null. GitHub owner/repo are trimmed and required, host omitted when blank. GitLab projectId/namespace/project/webUrl, Linear workspaceId/workspaceName/teamId/teamKey and Jira siteId/siteUrl/projectKey normalize to string-or-null. Stored forms reject wrong scalar types.',
  'Workspace context requires trimmed project/setup/repo/path; otherwise null. Repo context prefers normalized explicit executionHostId, then trimmed legacy connectionId as ssh:, else local. Runtime settings expose activeRuntimeEnvironmentId only for a runtime-owned host.',
  'Equality compares required identity fields and null-collapsed optional fields, independent of object key order. Cache scope percent-encodes provider, host, project, setup, repo and provider identity; this non-dispatch cache path calls githubRepoIdentityKey beyond the CLI payload normalizer.'
], [
  'Port task-source-context.test.ts with exact null/omitted object shapes and task-source-context-schema assertions; add direct-invalid-host versus stored-invalid-host contrast and malformed provider identities for every provider.',
  'Verify all required-empty workspace fields reject, invalid explicit host falls back as source does, and nested runtime+SSH ownership is never turned into a caller-side SSH dial.'
], ['githubRepoIdentityKey implementation and TaskSourceContextSchema were not reread here; their cache/schema behavior is separate from the manually reviewed CLI normalizer. Existing test imports do not establish their entire control flow.']);

add('S2-host', 'E4-S2', 'Execution host identity, scope and ownership', ['src/shared/execution-host.ts'], [
  'parseExecutionHostId trims outer input, recognizes exact local or ssh:/runtime: with nonempty encoded suffix, rejects raw pipe and malformed percent escapes, and requires a nonempty decoded suffix. It preserves original encoded suffix spelling in id; to* constructors encodeURIComponent the trimmed target.',
  'normalizeExecutionHostScope maps absent/blank/all/invalid to all; requestedExecutionHostScope first substitutes local only for nullish input. Therefore omission is local but explicit empty/invalid is all. Visible arrays drop malformed entries and duplicates in order; no valid entries =>null; order normalization uses [] instead.',
  'Repo ownership prefers valid explicit host then legacy connection then local. getRepoSshConnectionId answers where files live: runtime host can retain nested legacy SSH; explicit local suppresses contradictory SSH. getSshTargetIdForExecutionHost answers what this caller can dial and returns a target only for ssh:. Worktree hostId nullishly wins without revalidation, then populated repo ownership, then provided default.',
  'Focused environment maps to runtime:<encoded-id> or local. Labels use explicit platform or navigator Windows/Mac/Linux/X11 before process.platform; local labels Mac/Windows/Linux/This computer. Invalid ids label Unknown host, all labels All hosts; remote labels use decoded id. runtime-ssh- is a discriminator, not a distinct host namespace.'
], ['Port execution-host.test.ts and CLI execution-host-flag.test.ts; add percent-spelling identity comparisons, decoded whitespace, explicit empty scope versus omission, malformed worktree host override and runtime nested SSH fixtures on local/SSH/runtime axes.']);

add('S2-path', 'E4-S2', 'Cross-platform and WSL path interpretation', ['src/shared/cross-platform-path.ts', 'src/shared/wsl-paths.ts'], [
  'Ownership: syntax-driven path normalization can describe another OS; it does not perform filesystem I/O or imply the executing machine owns that path. Windows drive/plain UNC roots fold case; WSL UNC and POSIX roots preserve Linux/path tail case.',
  'Comparison keys normalize NFC and slash spelling for Windows-shaped paths while retaining literal POSIX backslashes; trim trailing slashes except roots. WSL aliases wsl.localhost/wsl$ canonicalize to //wsl/<lower-distro>/<case-preserved-tail>. That key is not safe to normalize twice: a second pass can treat //wsl as plain UNC and fold the tail.',
  'Containment requires equal or slash-delimited root prefix, with root exceptions. relativePathInsideRoot returns empty for equality, null outside, and the raw candidate suffix by segment count rather than normalized character count, preserving NFD/astral spelling and avoiding Unicode fold expansion slicing.',
  'WSL caller-Linux matching requires the same distro case-insensitively and case-sensitive Linux tail. Mounted /mnt/<drive> paths may match independent of distro when both are mounted drives. Ordinary UNC is not a WSL alias.',
  'parseWslUncPath accepts both aliases and slash types with exactly the required UNC prefix and nonempty distro; Linux tail defaults /. toLinuxPath unwraps WSL UNC only on win32 but converts drive paths to /mnt/<lower-drive> on every platform. toWindowsWslDrivePath only recognizes lowercase /mnt/lower-drive and excludes line terminators; otherwise toWindowsWslPath preserves a distro UNC view.',
  'resolveWslRepoWorktreeBasePath rewrites a single-leading-slash Linux absolute base under a WSL repo into its distro UNC, collapses dot segments, floors at root and preserves the UNC view for /mnt. Existing drive/UNC/relative bases and non-WSL repos stay unchanged.',
  'foldWslUncPathCaseInsensitiveParts folds server/distro, plus a lowercase /mnt mount tail; /MNT remains ordinary case-sensitive Linux. Filesystem-boundary label names distro for WSL-UNC DrvFs, or Windows-drive path with a selected WSL runtime; not ordinary Linux/UNC paths.',
  'resolveRuntimePath chooses Windows flavor when base/target syntax indicates it, resolves absolute targets directly and relative targets against base, removes dot segments without escaping absolute root, and retains leading .. only for relative paths. Windows rooted slash/backslash counts absolute in Windows flavor; POSIX only slash. UNC root includes server/share; basename splits both separators.'
], ['Port cross-platform-path.test.ts and wsl-paths.test.ts unchanged; add comparison-key non-idempotence characterization, mixed namespace/no-local-I/O route assertions, root traversal and invalid UNC shapes. Execute real Windows/WSL/macOS normalization and filesystem rejoin fixtures separately from platform stubs.']);

add('S2-key-linear-agent', 'E4-S2', 'Key grammar, Linear bounds and exact agent enum', [
  'src/shared/computer-use-key-spec.ts', 'src/shared/linear/agent-access.ts', 'src/shared/linear/uuid.ts', 'src/shared/tui-agent-config.ts', 'src/shared/tui-agent-selection.ts'
], [
  'Hotkey splits + and trims, requires >=2 nonempty parts and exactly one nonmodifier; matching lowercases and removes whitespace/_/-. Modifier set is alt,cmd,cmdorctrl,command,commandorcontrol,control,ctrl,meta,option,shift,super,win. Duplicate modifiers and unknown single base-key names are allowed. No normalized key string is returned; success is null and original CLI value is forwarded.',
  'Press-key requires trimmed nonempty single key; literal + is allowed, any other plus-bearing string rejects. Click-modifiers require 1..4 nonempty modifier tokens, case-fold only, with duplicate modifiers allowed; interior separators/whitespace aliases accepted by hotkey are not accepted here. Failures are stable validation hint strings, mapped by S1 handlers to invalid_argument.',
  'Linear search undefined/nonfinite defaults20; otherwise floor and clamp1..50. Depth undefined/nonfinite defaults2; otherwise floor/clamp0..5. Direct null/non-number values fail Number.isFinite and default; CLI numeric parser remains the outer contract. Caps/constants and TypeScript request/error unions in agent-access are declarations, not additional runtime validation. UUID accepts case-insensitive hex8-4-4-4-12 without version/variant enforcement.',
  'isTuiAgent requires typeof string and Object.hasOwn(TUI_AGENT_CONFIG,value), with no trim/case/alias normalization. Exact keys: claude, claude-agent-teams, openclaude, codex, autohand, ante, trae, opencode, mimo-code, pi, omp, prime-agent, gemini, antigravity, aider, goose, amp, kilo, kiro, crush, aug, cline, codebuff, command-code, continue, cursor, droid, kimi, mistral-vibe, qwen-code, rovo, hermes, openclaw, copilot, grok, devin. Detect aliases are not enum aliases.',
  'Disabled-agent normalization accepts arrays only, filters by isTuiAgent and deduplicates preserving order. Auto-pick returns null for blank preference, otherwise preferred if detected+enabled then explicit catalog priority, else null. These helpers do not establish provider installation or authenticate selected model.'
], ['Port computer-use-key-spec.test.ts and relevant Linear/automation CLI assertions from S1; add duplicate modifiers, unknown base key, normalization asymmetry, null/NaN/infinity/fraction clamp cases, UUID invalid hex/shape versus valid nonstandard version, and enum prototype/case/alias rejection.']);

add('S3-local', 'E4-S3', 'Bootstrap discovery, local stream framing and envelope', [
  'src/cli/runtime/transport.ts', 'src/cli/runtime/envelope-schema.ts', 'src/shared/runtime-rpc-envelope.ts', 'src/cli/runtime/metadata.ts', 'src/shared/runtime-bootstrap.ts', 'src/shared/timer-delay.ts'
], [
  'Caller opens a local unix socket or Windows named pipe described by its user-data metadata. findTransport chooses the FIRST matching entry in metadata array order, not an intrinsic unix-over-pipe priority. If an array exists, even empty, legacy singular transport is not consulted; otherwise supported legacy transport is accepted. Endpoint/auth/runtimeId/pid are not fully schema-validated by metadata reader.',
  'readMetadata JSON-parses, requires compatible transport and truthy authToken, preserves its own incomplete error and wraps read/parse errors as runtime_unavailable. tryReadMetadata returns null for read/parse error. User-data override is truthy ORCA_USER_DATA_PATH unchanged; otherwise macOS Application Support/orca, Windows APPDATA/orca (missing APPDATA throws), Linux XDG_CONFIG_HOME/orca or ~/.config/orca.',
  'sendRequest rejects timeout unless number safe integer0..2147483647 before discovery. Connect writes newline-delimited JSON with random request id, auth token, method, params and orchestration envelope fields; undefined keys disappear. Each data event appends UTF-8 text, splits complete newlines and ignores blank frames; no buffer cap is imposed here.',
  'Any object with _keepalive===true refreshes idle timeout before schema/id checks. Other frames must parse and match union schema then request id. Truthy response _meta.runtimeId differing from bootstrap rejects as runtime_unavailable; missing/null/empty failure metadata bypasses that check. JSON/schema/id errors are invalid_runtime_response.',
  'Success envelope is id:string, ok:true, unknown result, required _meta.runtimeId:string. Failure is id:string, ok:false, error code/message strings with optional unknown data and optional _meta.runtimeId:string|null. Keepalive is literal true. Zod strips additive unknown fields; result internals are unvalidated. Missing result behavior of z.unknown must be pinned by the installed Zod baseline, not inferred from TypeScript.',
  'Timeout destroys socket and yields runtime_timeout. Connect error or clean close before a response yields runtime_unavailable; finish is once-only, clears timer and ends socket. Transport returns failure envelopes without turning them into exceptions; RuntimeClient handles that later. These failures do not establish remote process exit.'
], ['Port transport.test.ts and runtime-client.test.ts; preserve prompt-close <5000ms assertion and keepalive-delayed success.', 'Add fragmented UTF-8/newline/coalesced/blank frames, wrong ids/runtime ids, additive keys, malformed union, missing result, failure metadata absent/null/empty, premature close, timer0 and maximum bounds. Port named-pipe fixtures on Windows because Unix suites explicitly skip it.', 'Characterize unbounded local buffer handling and malformed metadata (null transport entries, endpoint types) with disposable peers; do not label these execution debt as behavior already verified.']);

add('S3-client', 'E4-S3', 'Runtime client host selection, timeout and compatibility fencing', [
  'src/cli/runtime/client.ts', 'src/cli/runtime/remote-runtime-compat-gate.ts', 'src/cli/runtime/runtime-request-timeout.ts', 'src/shared/protocol-compat.ts', 'src/shared/orchestration-timing-budgets.ts', 'src/shared/orchestration-rpc-contract.ts'
], [
  'Constructor defaults request budget60s and local user-data path. Pairing defaults ORCA_PAIRING_CODE ?? ORCA_REMOTE_PAIRING; environment defaults ORCA_ENVIRONMENT. Truthy pairing+environment conflict rejects; environment resolves saved offer, absent pairing is local, malformed pairing invalid_argument. Remote calls lazily import WebSocket modules.',
  'Options.timeoutMs nullishly overrides method budget. Waiting orchestration.check requires wait===true; terminal.wait and waiting check use max(default, finite positive Number(params.timeoutMs)+10000). WorkerStart derives positive readiness else60000, adds50000ms transport grace, rejects unsafe/max timer overflow before preflight; default client budget can still dominate.',
  'Mutation set includes runCreate/runUse/send/reply/taskCreate/taskUpdate/workerStart/Stop/Abandon/Release/Retain/ask/gateCreate/gateResolve/reset/federationAttachStart/Ack/Import/Stop. Retired run/runStop are mutations. Check is mutation when ack is any string (including empty), otherwise read-only only for peek===true/all===true/unread===false; dispatch is read-only only dryRun===true. Names outside set are read-only at this helper.',
  'Every orchestration mutation first shares a cached status capability-check promise; rejection remains cached too. Missing orchestration.contract capability yields orchestration_migration_required and effectsApplied:false recovery guidance before requested mutation. Only mutations get durable orchestrationRequestId (explicit nullish override or UUID); all orchestration methods carry contract version and compatibility evidence/invocation id.',
  'Remote first non-status request performs status.get then requested RPC on one socket; checked clients and status.get bypass that preflight. Compatibility uses runtime version fields with legacy protocol/mobile fallback, missing=>0; client-too-old wins over server-too-old. Successful verified status sets checked=true; failures do not. Local ordinary RPC has no analogous protocol-version gate.',
  'RPC failures become RuntimeRpcFailureError with response metadata/data; transport RuntimeClientErrors receive mutation recovery details. Successful remote calls and successful preflight can persist markEnvironmentUsed on the CALLER even though work ran remotely; a persistence error may surface after remote effects succeeded. There is no automatic safe retry from failure alone.'
], ['Port runtime-client.test.ts, websocket-transport*.test.ts and orchestration-rpc-contract.test.ts; add concurrent/rejected cached preflight, dryRun false/string true, check ack empty/null with read-only flags, method timeout/grace maximum boundaries and environment store failure after remote success.', 'Execute old/current client-server version matrix in both directions; assert no requested mutation before capability gate, no fallback to local on remote loss, durable retry identity preserved and effects unknown after transport failure.']);

