  'src/cli/runtime/types.ts', 'src/cli/runtime/client-error-recovery.ts', 'src/cli/runtime/orchestration-compatibility-envelope.ts', 'src/shared/orchestration-compatibility-evidence.ts', 'src/cli/runtime/orchestration-recovery-command.ts'
